-- Run once (seed_runs). Assam Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/as/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Assam manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_as_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.
UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('784e9b60-7b8f-4c8d-8b9c-a2d254365258', 'dcf4f1db-a743-466b-bd67-1ee21b83f974', '6195990e-2c4f-4375-a6b7-1a4857857781', 'fbd09591-d1a1-555d-89bf-7440769422c7') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('784e9b60-7b8f-4c8d-8b9c-a2d254365258', 'dcf4f1db-a743-466b-bd67-1ee21b83f974', '6195990e-2c4f-4375-a6b7-1a4857857781', 'fbd09591-d1a1-555d-89bf-7440769422c7') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('784e9b60-7b8f-4c8d-8b9c-a2d254365258', 'dcf4f1db-a743-466b-bd67-1ee21b83f974', '6195990e-2c4f-4375-a6b7-1a4857857781', 'fbd09591-d1a1-555d-89bf-7440769422c7') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('784e9b60-7b8f-4c8d-8b9c-a2d254365258', 'dcf4f1db-a743-466b-bd67-1ee21b83f974', '6195990e-2c4f-4375-a6b7-1a4857857781', 'fbd09591-d1a1-555d-89bf-7440769422c7')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));
